int n;
vector<vector<int>> adj, radj;     // graph and its reverse
vector<bool> visited;
vector<int> order, comp;

void dfs1(int u) {
    visited[u] = true;
    for (int v : adj[u]) if (!visited[v]) dfs1(v);
    order.push_back(u);                       // finish-time order
}
void dfs2(int u, int c) {
    comp[u] = c;
    for (int v : radj[u]) if (comp[v] == -1) dfs2(v, c);
}
int kosaraju() {                              // returns number of SCCs
    visited.assign(n, false);
    for (int u = 0; u < n; ++u) if (!visited[u]) dfs1(u);
    comp.assign(n, -1); int c = 0;
    for (int i = n - 1; i >= 0; --i)          // reverse finish order
        if (comp[order[i]] == -1) dfs2(order[i], c++);
    return c;
}

def kosaraju(n, adj, radj):
    visited = [False]*n; order = []
    def dfs1(u):
        visited[u] = True
        for v in adj[u]:
            if not visited[v]: dfs1(v)
        order.append(u)
    for u in range(n):
        if not visited[u]: dfs1(u)
    comp = [-1]*n
    def dfs2(u, c):
        comp[u] = c
        for v in radj[u]:
            if comp[v] == -1: dfs2(v, c)
    c = 0
    for u in reversed(order):
        if comp[u] == -1:
            dfs2(u, c); c += 1
    return comp, c
